\begin{proposition}[2-Chu Extent--Transversal Galois Duality and Maximal-vs.-Minimal Reconciliation]\label{ch01:prop:extent-transversal-galois}%
\uses{vol1:def:doctrinal-philosophy,ch01:def:probe-suite,ch01:def:adm-pareto-frontier}%
Over any $2$-Chu pairing~\cite{shulman2020} $I : \mathbb{D} \times \mathcal{P} \to \mathbf{Bool}$ for $\Phi = (H, C, K)$ ({{ref:ch01:def:probe-suite}}), the maps $\mathrm{Th}_I : \mathcal{P}(\mathbb{D}) \rightleftarrows \mathcal{P}(\mathcal{P})^{\mathrm{op}} : \mathrm{Ext}_I$ form an antitone Galois connection ($\mathrm{Th}_I(U) \supseteq Q \iff U \subseteq \mathrm{Ext}_I(Q)$). Restricting to admissible closed extents $E \in \mathcal{M}_{[K,T]}$ ({{ref:ch01:def:adm-pareto-frontier}}) and admissible probe bundles $Q$ ($K \subseteq \mathrm{Ext}_I(Q) \subseteq T$) yields an order-reversing bijection up to extent equivalence ($\mathrm{Ext}_I(\mathrm{Th}_I(E)) = E$, $\mathrm{Ext}_I(\mathrm{Th}_I(\mathrm{Ext}_I(Q))) = \mathrm{Ext}_I(Q)$), under which
\[
  E = \mathrm{Ext}_I(Q) \in {{sym:pareto-res}}(H \Rightarrow C)
  \quad\Longleftrightarrow\quad
  Q \text{ is a refinement-minimal Prime Transversal.}
\]
\end{proposition}
\begin{proof}
Constructively without axioms, $\forall p \in Q,\; \forall d \in U,\; I(d, p) = \mathrm{true}$ rearranges quantifier order directly to $\forall d \in U,\; \forall p \in Q,\; I(d, p) = \mathrm{true}$, giving the Galois connection. Because $E$ is admissible iff $E = \mathrm{Ext}_I(\mathrm{Th}_I(E))$ and $K \subseteq E \subseteq T$, an admissible bundle $Q'$ has larger extent $\mathrm{Ext}_I(Q) \subseteq \mathrm{Ext}_I(Q')$ iff $Q'$ is strictly weaker deductively; hence inclusion-maximality of $E = \mathrm{Ext}_I(Q)$ in Volume~I's $\mathcal{M}_{[K,T]}$ ({{ref:vol1:def:doctrinal-philosophy}}) coincides identically with refinement-minimality of Prime Transversals in Volume~II.
\end{proof}

\begin{theorem}[Flow~F4 Split-Polarity Transport Law]\label{ch01:thm:flow-f4-split-polarity-transport}%
\uses{vol1:def:doctrinal-philosophy,ch01:def:probe-suite,ch01:prop:extent-transversal-galois}%
Let $(F : \mathbb{D}_1 \to \mathbb{D}_2,\; G : \mathcal{P}_2 \to \mathcal{P}_1)$ be a mixed-variance conversion morphism in {{sym:phil-cat}}~\cite{shulman2020} preserving cores and obstructions ($F[K_1] \subseteq K_2$, $F[W_1] \subseteq W_2$) relative to {{ref:ch01:def:probe-suite}} and {{ref:ch01:prop:extent-transversal-galois}}. Assume the \textbf{Split-Polarity Law}:
\begin{enumerate}[label=\textup{(\arabic*)},leftmargin=2.0em]
  \item \textbf{Oplax Core Preservation:} $\forall k \in K_1,\; \forall p_2 \in \mathcal{P}_2,\quad I_2(F(k), p_2) \le I_1(k, G(p_2))$;
  \item \textbf{Lax Obstruction Hitting:} $\forall w \in W_1,\; \forall p_2 \in \mathcal{P}_2,\quad I_1(w, G(p_2)) \le I_2(F(w), p_2)$.
\end{enumerate}
Then for every admissible transversal $\Theta_2 \subseteq \mathcal{P}_2$ on $\mathfrak{A}_2$, its direct image $G[\Theta_2] := \{G(p_2) \mid p_2 \in \Theta_2\} \subseteq \mathcal{P}_1$ is an admissible transversal on $\mathfrak{A}_1$. In particular, under a strict $2$-Chu adjunction $I_2(F(d), p_2) = I_1(d, G(p_2))$, Touchstone hyperedges pull back on the nose:
\[
  H_{K_2}(F(w)) \;=\; G^{-1}\bigl(H_{K_1}(w)\bigr).
\]
\end{theorem}
\begin{proof}
Constructively without axioms: for any $k \in K_1$ and $G(p_2) \in G[\Theta_2]$ ($p_2 \in \Theta_2$), $F(k) \in K_2$ gives $I_2(F(k), p_2) = \mathrm{true}$, whence oplax core preservation yields $I_1(k, G(p_2)) = \mathrm{true}$. Dually, for any $w \in W_1$, $F(w) \in W_2$ produces $p_2 \in \Theta_2$ with $I_2(F(w), p_2) = \mathrm{false}$; if $I_1(w, G(p_2)) = \mathrm{true}$, lax obstruction hitting would force $I_2(F(w), p_2) = \mathrm{true}$, contradiction, so $I_1(w, G(p_2)) = \mathrm{false}$. Under $I_2(F(d), p_2) = I_1(d, G(p_2))$, both polarity inequalities hold identically and $p_2 \in H_{K_2}(F(w)) \iff I_2(F(w), p_2) = \mathrm{false} \iff I_1(w, G(p_2)) = \mathrm{false} \iff G(p_2) \in H_{K_1}(w)$.
\end{proof}
